test('SCHEMA 別版の拒否', () => {
  const p = makeDefaultProject();
  p.appVersion = '9.9';
  reject(() => validateProject(p), 'F501');
});

await test('T09-VERSION-CONTRACT', async () => {
  const expected = {
    appVersion: '0.9',
    runtimeVersion: '0.9',
    languageVersion: '0.9',
    programFormatVersion: 2,
    projectFormatVersion: 2,
  };
  if (JSON.stringify(AKARI_RUNTIME.EXECUTABLE_VERSION) !== JSON.stringify(expected))
    throw new Error('実行版の契約が一致しません');
  const p = makeDefaultProject(),
    text = serializeProject(p, new AssetStore());
  if (
    !text.startsWith('# あかり 0.9 の作品') ||
    !text.includes('<!-- AKARI09-DATA-BEGIN -->') ||
    !text.includes('<!-- AKARI09-DATA-END -->')
  )
    throw new Error('作品の版またはマーカーが一致しません');
  const loaded = await parseProjectFile(text);
  if (JSON.stringify(loaded.project) !== JSON.stringify(p))
    throw new Error('0.9作品の往復で変化しました');
});

await test('T09-VERSION-REJECT-PROJECT', async () => {
  for (const version of ['0.7', '0.8', '1.0'])
    for (const key of ['appVersion', 'languageVersion']) {
      const p = makeDefaultProject();
      p[key] = version;
      await reject(() => serializeProject(p, new AssetStore()));
    }
  const current = serializeProject(makeDefaultProject(), new AssetStore());
  for (const old of ['AKARI07', 'AKARI08'])
    await reject(() => parseProjectFile(current.replaceAll('AKARI09', old)));
});

await test('T09-VERSION-REJECT-EXECUTABLE', async () => {
  for (const version of ['0.7', '0.8', '1.0'])
    for (const key of ['appVersion', 'languageVersion', 'runtimeVersion']) {
      const payload = packExecutable(makeDefaultProject(), new AssetStore());
      payload[key] = version;
      await reject(() => AKARI_RUNTIME.restoreExecutable(payload));
    }
  const p = makeDefaultProject(),
    payload = packExecutable(p, new AssetStore()),
    restored = AKARI_RUNTIME.restoreExecutable(payload);
  if (restored.project.name !== p.name || restored.compiled.errors?.length)
    throw new Error('0.9実行作品を復元できません');
});

await test('SCHEMA wrong release duplicate IDs invalid data and excessive input', async () => {
  const bad = make();
  bad.appVersion = '0.7';
  await reject(() => A.serializeProject(bad), 'F501');
  const dup = make();
  dup.projectData.variables[0].id = dup.components[0].id;
  await reject(() => A.serializeProject(dup), 'F505');
  const inf = make();
  inf.projectData.variables[0].initialValue = Infinity;
  await reject(() => A.serializeProject(inf));
  await reject(() => A.parseProjectFile('x'.repeat(A.LIMITS.fileBytes + 1)), 'F504');
});

await test('MARKDOWN readable code initial data and material manifest', async () => {
  const p = make(say('\u300c\u4fdd\u5b58\u8a66\u9a13\u300d')),
    s = A.serializeProject(p);
  ok(s.startsWith('# '));
  for (const part of [p.scripts[0].source, N, L, 'SHA-256', 'AKARI09-DATA-BEGIN'])
    ok(s.includes(part) || (part === 'SHA-256' && !p.sounds.length));
  const r = await A.parseProjectFile(s);
  eq(r.project, p);
});
